#include <iostream>
#include <vector>
#include <string>
#include <algorithm>
using namespace std;

using ll = long long;

const ll MOD = 1000000007LL;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, x;
    string s;
    cin >> n >> x >> s;

    vector<ll> pf2(max(2, x + 1), 2);
    for (int i = 2; i <= x; ++i) {
        pf2[i] = pf2[i - 1] * pf2[i - 2] % MOD;
    }

    const int size = n * n;
    vector<vector<ll>> dp(3, vector<ll>(size, 0));

    auto id = [n](int left, int right) {
        return left * n + right;
    };

    for (int i = 0; i < n; ++i) {
        dp[0][id(i, i)] = (s[i] == '0');
        dp[1][id(i, i)] = (s[i] == '1');
    }

    if (x <= 1) {
        cout << dp[x][id(0, n - 1)] << '\n';
        return 0;
    }

    for (int k = 2; k <= x; ++k) {
        auto& current = dp[k % 3];
        const auto& previous = dp[(k - 1) % 3];
        const auto& previous2 = dp[(k - 2) % 3];

        fill(current.begin(), current.end(), 0);

        for (int left = 0; left < n; ++left) {
            for (int right = left; right < n; ++right) {
                ll result = previous2[id(left, right)];
                if (left == 0) {
                    result = result * pf2[k - 1] % MOD;
                }

                ll term = previous[id(left, right)];
                if (right == n - 1) {
                    term = term * pf2[k - 2] % MOD;
                }
                result = (result + term) % MOD;

                for (int middle = left; middle < right; ++middle) {
                    result += previous[id(left, middle)] *
                              previous2[id(middle + 1, right)] % MOD;
                    if (result >= MOD) result -= MOD;
                }

                current[id(left, right)] = result;
            }
        }
    }

    cout << dp[x % 3][id(0, n - 1)] << '\n';
    return 0;
}

