#include <iostream>
#include <vector>
#include <string>
#include <algorithm>

using namespace std;

using ll = long long;

constexpr ll MOD = 1000000007LL;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, x;
    string s;
    if (!(cin >> n >> x >> s)) return 0;

    vector<ll> pf2(max(2, x + 1), 2);
    for (int k = 2; k <= x; ++k) {
        pf2[k] = pf2[k - 1] * pf2[k - 2] % MOD;
    }

    const size_t stateCount = static_cast<size_t>(n) * n;
    vector<ll> dp[3];
    for (auto& layer : dp) layer.assign(stateCount, 0);

    auto id = [n](int left, int right) -> size_t {
        return static_cast<size_t>(left) * n + right;
    };

    for (int i = 0; i < n; ++i) {
        dp[0][id(i, i)] = (s[i] == '0');
        dp[1][id(i, i)] = (s[i] == '1');
    }

    if (x <= 1) {
        cout << dp[x][id(0, n - 1)] << '\n';
        return 0;
    }

    for (int k = 2; k <= x; ++k) {
        auto& current = dp[k % 3];
        const auto& previous = dp[(k - 1) % 3];
        const auto& beforePrevious = dp[(k - 2) % 3];

        fill(current.begin(), current.end(), 0);

        for (int length = 1; length <= n; ++length) {
            for (int left = 0; left + length <= n; ++left) {
                int right = left + length - 1;
                ll result = 0;

                ll leftMultiplier = (left == 0 ? pf2[k - 1] : 1LL);
                result = leftMultiplier * beforePrevious[id(left, right)] % MOD;

                ll rightMultiplier = (right == n - 1 ? pf2[k - 2] : 1LL);
                result = (result +
                          previous[id(left, right)] * rightMultiplier) % MOD;

                for (int middle = left; middle < right; ++middle) {
                    result = (result +
                              previous[id(left, middle)] *
                              beforePrevious[id(middle + 1, right)]) % MOD;
                }

                current[id(left, right)] = result;
            }
        }
    }

    cout << dp[x % 3][id(0, n - 1)] << '\n';
    return 0;
}

